(function(){
  const p={};Game.res=(f,n)=>`resources/${f}/${n}`;
  const load=(k,get,src,msg)=>get()?Promise.resolve(get()):p[k]||(p[k]=new Promise((ok,no)=>{
    const s=document.createElement('script');s.src=src;
    s.onload=()=>get()?ok(get()):(p[k]=null,s.remove(),no(new Error(`${msg}未注册`)));
    s.onerror=()=>{p[k]=null;s.remove();no(new Error(`${msg}加载失败`))};
    document.head.appendChild(s);
  }));
  Game.loadRes=(f,n,get)=>load(`r:${f}/${n}`,get,Game.res(f,n),'资源');
  Game.load3D=()=>load('3d',()=>window.GR3,'vendor/three/gr3.min.js?v=185','3D 引擎');
  Game.loadNet3D=()=>load('net',()=>Game.Net3D,'js/net3d.js?v=3','展开图引擎');
  Game.loadGeometry=()=>Promise.all([Game.load3D(),Game.loadNet3D()]);
})();


