(function(){
const clean=s=>String(s).replace(/[。！？!?；;，,]+$/,'');
const sh=a=>a.map(v=>[Math.random(),v]).sort((x,y)=>x[0]-y[0]).map(x=>x[1]);
const R=(q,a,pool,hint,solution)=>({q,a:clean(a),pool:sh([...new Set(pool.map(clean))]),hint,solution});
const q=(id,title,tags,mk,extra={})=>Object.assign({id,title,t:title,tags,type:tags[0],makeQuestion:mk,mk},extra);
const c=(id,title,subs,extra={})=>Object.assign({id,title,t:title,type:'同卡子级别',tags:'同卡子级别',subs},extra);
const ask=(stem,answer,options,hint,solution)=>()=>R(stem,answer,options,hint,solution);
const seq={levelType:'sequence',unlockMode:'sequence',randomMode:'coverage',randomLabel:'路线后随机'};
const add=x=>Game.addLessonTopic('quantitative_relations_lesson_01',x);
Game.beginLesson('quantitative_relations_lesson_01','数量关系 01｜特值与零参照');
window.QR1={R,q,c,ask,seq,add,done:()=>Game.finishLesson('quantitative_relations_lesson_01',{title:'数量关系 01｜特值与零参照'})};
})();


