const line2compositecss=`<style class="line2compositecss">.lx2method{display:grid;gap:4px;padding:9px 11px;border-bottom:1px solid rgba(7,63,82,.09);background:linear-gradient(135deg,rgba(255,240,90,.22),rgba(23,232,255,.13))}.lx2method b{font-size:13px;color:#087b7e}.lx2method span{overflow-wrap:anywhere;font-size:13px;font-weight:950;line-height:1.45;color:rgba(7,63,82,.86)}.lx2method small{font-size:12px;font-weight:850;line-height:1.4;color:rgba(7,63,82,.62)}.lx2track.keep{grid-template-columns:auto minmax(0,1fr);padding-block:8px;background:rgba(255,255,255,.28)}.lx2track.keep .lx2keepnum{display:flex;align-items:center;justify-content:center;gap:8px}.lx2track.keep .lx2keepnum>span:last-child{font-size:12px;font-weight:900;color:rgba(7,63,82,.58)}.lx2track.keep .lx2trackmeta{grid-column:2;grid-row:1}.lx2sum em{font-style:normal;font-size:12px;font-weight:900;color:#087b7e}.lx2pick button small{line-height:1.2}@media(max-width:460px){.lx2track.keep .lx2trackmeta{grid-column:2}.lx2method span{font-size:12px}}</style>`;
const line2layoutcss=`<style class="line2layoutcss">.lx2target{flex-wrap:wrap}.lx2trackmeta{flex-wrap:wrap;white-space:normal}.lx2derive{grid-column:1/-1;grid-row:3;margin-top:1px;padding:0;border:1px dashed rgba(7,63,82,.14);border-radius:6px;background:rgba(255,255,255,.48)}.lx2derive summary{padding:7px 9px;cursor:pointer;list-style:none;font-size:12px;font-weight:950;color:rgba(7,63,82,.7)}.lx2derive summary::-webkit-details-marker{display:none}.lx2derive summary:after{content:"＋";float:right;color:#087b7e}.lx2derive[open] summary:after{content:"－"}.lx2derive>span{display:block;margin:0 8px 6px;padding-left:17px}.lx2derive>span:last-child{margin-bottom:8px}.lx2composite .lx2pick{grid-template-columns:1fr}.lx2composite .lx2pick button{grid-template-columns:minmax(88px,.8fr) minmax(0,1.2fr);grid-template-areas:"name value" "meta meta";row-gap:4px}.lx2composite .lx2pick button b{grid-area:name}.lx2composite .lx2pick button span{grid-area:value;text-align:right;overflow-wrap:anywhere}.lx2composite .lx2pick button small{grid-area:meta;white-space:normal;overflow-wrap:anywhere;color:rgba(7,63,82,.6)}.lx2pure .lx2pick button small{white-space:normal}.lx2method span,.lx2method small,.lx2formula{overflow-wrap:anywhere}.lx2exact{row-gap:4px}@media(max-width:620px){.lx2{font-size:12px}.lx2pick{grid-template-columns:1fr}.lx2head{padding:8px}.lx2target{gap:6px;padding:7px}.lx2target>b{font-size:16px}.lx2track{grid-template-columns:auto minmax(0,1fr);padding:8px}.lx2swap{grid-template-columns:minmax(78px,1fr) auto minmax(78px,1fr)}.lx2trackmeta{grid-column:1/-1;grid-row:3;justify-content:center;text-align:center}.lx2track.keep .lx2trackmeta{grid-column:1/-1;grid-row:3}.lx2derive{grid-row:4}.lx2join{padding:7px}.lx2calc{grid-template-columns:1fr;gap:4px}.lx2calc>i{transform:rotate(90deg);font-size:14px}.lx2calc>span{padding:6px}.lx2exact{display:grid;grid-template-columns:1fr;text-align:center}.lx2know,.lx2all{grid-template-columns:1fr}.lx2k:last-child{grid-column:auto}.lx2method{padding:8px}.lx2method span{font-size:12px}.lx2fork{width:min(100%,240px)}}@media(max-width:390px){.lx2digits i{width:20px;height:27px;font-size:15px}.lx2digits.mini i{width:17px;height:24px;font-size:13px}.lx2swap{grid-template-columns:minmax(68px,1fr) auto minmax(68px,1fr);gap:4px}.lx2composite .lx2pick button{grid-template-columns:1fr;grid-template-areas:"name" "value" "meta"}.lx2composite .lx2pick button span{text-align:left}}</style>`;
const linePureQ=()=>{const cfg=line2cfg(),safeLimit=cfg.safeLimit,safeLabel=line2trim(safeLimit,1),frac=(n,z)=>`<span class="lx2frac"><i>${line2fmt(n)}</i><i>${line2fmt(z)}</i></span>`,digits=(v,c='')=>`<span class="lx2digits${c?' '+c:''}">${[...String(v)].map(x=>`<i>${x}</i>`).join('')}</span>`,rawfrac=(n,z)=>`<div class="lx2rawfrac"><div>${digits(n)}</div><div>${digits(z)}</div></div>`,move=c=>`${c.dir==='上升'?'↑':'↓'}${DA.rs(c.pct,1)}%`,gap=p=>p.resultPct<.01?'&lt;0.01%':`${DA.rs(p.resultPct,2)}%`,axis=p=>`<div class="lx2scale${p.pct>=safeLimit?' over':''}" style="--w:${Math.min(100,p.pct/safeLimit*100)}%"><div class="lx2axis"><span>0</span><b>${p.pct>=safeLimit?`实际 ${p.pt}%｜超界`:`总和偏移 ${p.pt}%`}</b><span>${safeLabel}%</span></div><div class="lx2meter"><i></i></div></div>`,track=(t,v,c)=>`<section class="lx2track ${t==='分子'?'num':'den'}"><strong>${t}</strong><div class="lx2swap">${digits(v.raw,'mini cut')}<span>→</span>${digits(v.easy,'mini')}</div><div class="lx2trackmeta"><span class="${c.dir==='上升'?'up':'down'}">${move(c)}</span><strong class="${c.corr>0?'pos':c.corr<0?'neg':'zero'}">修正 ${c.term}</strong></div><details class="lx2derive"><summary>误差百分率怎么来</summary>${c.derive.steps.map((s,i)=>`<span data-step="${i+1}">${s}</span>`).join('')}</details></section>`,view=p=>`<section class="lx2target"><span>当前好算骨架</span>${frac(p.divView.easyN,p.divView.easyD)}<b>= ${p.divView.answer}</b></section>${track('分子',p.l,p.cs[0])}${track('分母',p.r,p.cs[1])}<section class="lx2join"><div class="lx2fork"><i></i><b>线性合流</b><i></i></div><div class="lx2formula">${p.formula}</div><div class="lx2net">Σ ${p.netTerm}</div>${axis(p)}</section><strong class="lx2resulttitle">修正结果</strong><div class="lx2calc"><span>粗算<b>${line2fmt(p.rough)}</b></span><i>→</i><span>${p.fix}修正<b>${line2fmt(p.adj)}</b></span><i>→</i><span>估算<b>${line2fmt(p.result)}</b></span></div><div class="lx2exact"><span>机器精算值 <b>${line2fmt(p.real)}</b></span><span>当前估算值 <b>${line2fmt(p.result)}</b></span><small>当前估算比精算${p.result<p.real?'低':'高'} ${gap(p)}</small></div>`,sum=(p,i,best)=>`<section class="lx2sum${p.pct>=safeLimit?' over':''}" style="${Math.abs(p.resultPct-best)<1e-12?'border-color:rgba(0,138,120,.34);background:rgba(223,255,248,.82)':''}"><b>0${i+1}｜${p.plan}</b><strong>${line2fmt(p.divView.easyN)} ÷ ${line2fmt(p.divView.easyD)} = ${p.divView.answer}</strong><span>净偏移 ${p.netTerm}${p.pct>=safeLimit?'｜超界':''}${Math.abs(p.resultPct-best)<1e-12?'｜误差最小':''}｜估算 ${line2fmt(p.result)}</span><small>精算 ${line2fmt(p.real)}｜偏${p.result<p.real?'低':'高'} ${gap(p)}</small></section>`;return Object.assign(R('只使用纯划线法：同时主动改造分子和分母，再合并两边误差。','ok',['ok'],'',''),{free:1,perfectFree:1,mount:x=>{const plans=linePureData(),best=Math.min(...plans.map(p=>p.resultPct)),raw=plans[0].divView,know=`<div class="lx2know"><section class="lx2k"><b>纯划线法</b><span>本分支只训练主动改数、判断方向和线性合流，不调用直接百化分，也不优先保留某一边。</span></section><section class="lx2k"><b>分子反向</b><span>分子放大，真实结果向下修；分子缩小，真实结果向上修。</span></section><section class="lx2k"><b>分母同向</b><span>分母放大，真实结果向上修；分母缩小，真实结果向下修。</span></section><section class="lx2k"><b>两级误差尺子</b><span>先把前两位凑顺、后面清零时，0.5% 内的千分级前置误差可忽略；其余真正改数误差仍按 0.25%～0.75% 记 0.5% 的规则取档。</span></section><section class="lx2k"><b>安全线 ${safeLabel}%</b><span>单边改动和合流后的总偏移都要检查是否越界。</span></section></div>`,all=`<p class="lx2intro">五种方案沿用原来的纯划线法结构：轻改、平衡、大步、超界和整位。综合识别另放在下一分支，不会覆盖这里。</p><div class="lx2all">${plans.map((p,i)=>sum(p,i,best)).join('')}</div>`;x.setQ('只用纯划线法，把分子、分母改成好算骨架，再把两边误差合流。');x.setC(`${line2css}${line2trackcss}${line2layoutcss}<div class="lx2 lx2pure"><div class="lx2stage"><section class="lx2head"><span>同一道随机原式</span>${rawfrac(raw.rawN,raw.rawD)}</section><div class="lx2pick">${plans.map((p,i)=>`<button type="button" data-lxp="${i}"><b>${p.plan.replace('方案','')}</b><span>${line2fmt(p.divView.easyN)}÷${line2fmt(p.divView.easyD)}</span><small>${p.netTerm}</small></button>`).join('')}</div><div class="lx2body"></div></div><div class="lx2folds">${foldHtml('lxpknow','基础知识',know,x.pf,1)}${foldHtml('lxpall','五种方案对照',all,x.pf,1)}</div></div>`);const root=x.el.querySelector('.lx2pure'),draw=i=>{const p=plans[i];root.querySelector('.lx2body').innerHTML=view(p);root.querySelectorAll('[data-lxp]').forEach((b,j)=>b.classList.toggle('on',i===j));x.setFb(p.pct>=safeLimit?`${p.plan}｜实际总偏移 ${p.pt}%｜超出 ${safeLabel}% 建议边界`:`${p.plan}｜净修正 ${p.netTerm}｜当前估算比精算${p.result<p.real?'低':'高'} ${gap(p)}`);x.refresh()};root.querySelector('.lx2pick').onclick=e=>{const b=e.target.closest('[data-lxp]');b&&draw(+b.dataset.lxp)};bindFolds(root,()=>x.refresh());draw(1);x.setReplay()}})};
