const toolCompare01=()=>{const fracItem=DA.pk(percentSupplier.basic().filter(x=>x.skeleton.length>1)),num=fracItem.decimalPlain,frac=fracItem.fraction,[raw,easy]=DA.pk([[1034,1000],[397,400],[2345,2400],[9763,10000],[6827,7000],[4513,4500]]),pct=Math.abs(easy-raw)/raw*100,dir=easy>raw?'上升':'下降',err=pct<1?`${(pct*10).toFixed(1)}‰`:`${pct.toFixed(1)}%`;return `<style class="tool01css">.tool01{width:min(100%,360px);margin:10px auto 0;overflow:hidden;border:1px solid rgba(7,63,82,.1);border-radius:7px;background:rgba(255,255,255,.46);box-shadow:inset 0 1px 0 rgba(255,255,255,.62),0 5px 12px rgba(0,75,118,.06);color:rgba(7,63,82,.9);text-align:left}.tool01r{display:grid;grid-template-columns:10px minmax(46px,58px) 12px minmax(46px,58px) minmax(90px,1fr);gap:8px;align-items:center;min-height:72px;padding:10px 12px}.tool01r+.tool01r{border-top:1px solid rgba(7,63,82,.09)}.tool01d{width:10px;height:28px;background:#39c5bb}.tool01line .tool01d{background:#ffa500}.tool01n,.tool01v{display:grid;place-items:center;min-height:34px;border:1px solid rgba(7,63,82,.11);background:rgba(255,255,255,.82);font-size:18px;font-weight:950}.tool01v{background:rgba(255,226,17,.22)}.tool01a{text-align:center;font-size:16px;font-weight:950;color:rgba(7,63,82,.48)}.tool01m{min-width:0}.tool01m b,.tool01m small{display:block}.tool01m b{font-size:13px}.tool01m small{margin-top:3px;font-size:13px;font-weight:850;line-height:1.4;color:rgba(7,63,82,.62)}.tool01f{padding:8px 12px;border-top:1px solid rgba(7,63,82,.09);background:rgba(255,226,17,.14);font-size:14px;font-weight:900;line-height:1.45;text-align:center;color:rgba(7,63,82,.72)}</style><div class="tool01" role="group" aria-label="分数转化与划线法对比"><div class="tool01r tool01frac"><i class="tool01d"></i><strong class="tool01n">${num}</strong><span class="tool01a">→</span><strong class="tool01v">${frac}</strong><span class="tool01m"><b>分数转化</b><small>熟悉骨架直接借分数</small></span></div><div class="tool01r tool01line"><i class="tool01d"></i><strong class="tool01n">${raw}</strong><span class="tool01a">→</span><strong class="tool01v">${easy}</strong><span class="tool01m"><b>划线法</b><small>${dir}约 ${err}</small></span></div><div class="tool01f">分数转化依赖熟悉骨架；划线法不挑数字，更通用，也通常更常用。</div></div>`};
