const train01=mode=>{let body=mode==='material'?`<div class="train01row"><div class="train01box a">真题<br>完整流程</div><div class="train01box b">随机数<br>单点反应</div><div class="train01box c">生活数<br>碎片练习</div></div><div class="train01cap">先定训练目标，再取对应素材</div>`:mode==='action'?`<div class="train01cut"><i></i><i></i><i></i><i></i></div><div class="train01row train01flow"><div class="train01box a">看见</div><span class="train01arrow">→</span><div class="train01box b">判断</div><span class="train01arrow">→</span><div class="train01box c">作答</div></div><div class="train01cap">把整题拆成可重复的小动作</div>`:`<div class="train01loop"><div class="train01dot">一题</div><div class="train01dot">反馈</div><div class="train01dot">再来</div></div><div class="train01cap">短、快、重复，直到反应不再需要提醒</div>`;return `${train01css}<div class="train01"><div class="train01stage">${body}</div></div>`};
