const mindFx=(key,p,a,b)=>{const dots=(n,on=n)=>Array.from({length:n},(_,j)=>`<i class="${j<on?'on ':''}${j===on?'stop ':''}"></i>`).join(''),v={
  exam:`<div class="mx mxmindscene mxmindexam"><section class="mxmindpaper mxcard"><header><b>${p[0]}的国考答题卡</b><span>资料分析</span></header><div class="mxqgrid">${dots(20,16)}</div><div class="mxmindcalc"><span><small>一眼粗算</small><b>≈ 267</b></span><i>→</i><span class="stall"><small>不敢相信</small><b>退回精算</b></span></div></section><aside class="mxmindclock"><small>计时器还在走</small><b>01:18</b><small>会估，却不敢落笔</small></aside></div>`,
  rail:`<div class="mx mxmindscene mxrail"><div class="mxrailtop"><span>G · 返程</span><i></i><small>国考后</small></div><div class="mxrailwin"><div class="mxrailsky"></div><div class="mxrailcity"></div><div class="mxrailnear"><i></i><i></i><i></i><i></i><i></i><i></i></div><div class="mxrailglass"></div><div class="mxrailref"><i></i><b></b></div><span class="mxrailplace">返程高铁 · 靠窗</span></div><div class="mxrailthought"><span><small>平时练习</small><b>一眼能报近似值</b></span><i></i><span><small>真正考场</small><b>却不敢落笔</b></span></div></div>`,
  home:`<div class="mx mxmindscene mxreason"><div class="mxreasonhead"><b>${p[0]}把卡点说出来</b><span>复盘开始</span></div><div class="mxvalue"><section class="rough mxcard"><small>平时</small><b>会估</b></section><i>→</i><section class="judge mxcard"><small>考场</small><b>不敢用</b></section></div><div class="mxcircle">问题不是速度，而是快值没有边界。</div></div>`,
  direction:`<div class="mx mxmindscene mxreason"><div class="mxreasonhead"><b>${b[0]}把问题拆开</b><span>先判断方向</span></div><div class="mxvalue"><section class="rough mxcard"><small>粗算值</small><b>270</b></section><i>→</i><section class="judge mxcard"><small>第一层判断</small><b>偏大</b></section></div><div class="mxcircle">方向说得清，才知道答案该往哪边拉。</div></div>`,
  range:`<div class="mx mxmindscene mxreason"><div class="mxreasonhead"><b>${a[0]}继续往下问</b><span>再判断范围</span></div><div class="mxband"><span class="zone"></span><span class="cursor"></span><span class="mark m1">264</span><span class="mark m2">267</span><span class="mark m3">270</span></div><div class="mxcircle">误差会不会跨过相邻选项，决定现在能不能停算。</div></div>`,
  fix:`<div class="mx mxmindscene mxfix"><header><b>把误差带回来</b><span>方向 · 范围 · 修正</span></header><div class="mxfixflow"><section class="mxcard"><small>粗算</small><b>270</b></section><i>→</i><section class="mxcard"><small>下修约</small><b>3</b></section><i>→</i><section class="mxcard"><small>稳定落点</small><b>267</b></section></div><div class="mxfixcap">不是背住 267，而是把判断链练到能直接调用。</div></div>`,
  ready:`<div class="mx mxmindscene mxready"><aside class="mxreadyaside"><small>湖南 3·15 联考</small><b>很稳</b><span>不赶高铁</span></aside><section class="mxcheck"><span>方向已经练过</span><span>范围已经练过</span><span>修正已经练过</span></section></div>`,
  focus:`<div class="mx mxmindscene mxmindfocus"><section class="mxanswer mxcard"><strong>${p[0]}的联考答题卡</strong><div class="mxmindline"><span>粗算偏大</span><span>约 1% 多</span><span>不会跨项</span></div><div class="mxopts4"><i></i><i class="on"></i><i></i><i></i></div></section><aside class="mxmindnext"><b>判断结束</b><span>继续下一题</span></aside></div>`,
  wait:`<div class="mx mxmindscene mxready"><aside class="mxreadyaside"><small>省考结束</small><b>已交卷</b><span>等待出分</span></aside><section class="mxcheck"><span>方向判断完成</span><span>误差范围稳定</span><span>答案已经落定</span></section></div>`,
  legend:`<div class="mx mxmindscene mxlegend"><section class="mxlegendscore"><section class="mxcard"><small>${p[0]}笔试成绩</small><b>180</b></section><section class="mxcard"><small>全省第二名</small><b>150</b></section><div class="mxgap30">领先整整 <b>30</b> 分</div></section><aside class="mxlegendend"><small>全省排名</small><b>第一</b><span>稳定兑现</span></aside></div>`
};return v[key]?methodCss+mindCss+mindFixCss+railCss+railPolishCss+v[key]:''};
const galInstant=ss=>ss.map(s=>{const z=Object.assign({},s,{ms:1},s.end?{endDelay:1}:{});if(!z.end&&(!Array.isArray(z.o)||!z.o.length))z.o=[['继续',1]];return z});
const mindQ=()=>R('考场心理建设','结局',['结局'],'','国考时不敢用估算，不是因为算得不够快，而是快值没有边界。返程高铁上的失落只是起点，真正的改变发生在回家后的坦诚复盘：把偏差方向、误差范围和修正方法练成一条判断链。到了湖南 3·15 联考，不必临场鼓劲，也不必回想谁说过什么；看清误差能否跨过选项，够用就直接作答。最终笔试 180 分，全省第二名 150 分，整整领先 30 分。这不是偶然爆发，而是结果可解释、误差可控制、答案可修正之后的稳定兑现；从国考时不敢相信估算，到成为全省传说，这 30 分正是方法真正内化后的分量。',{perfectFree:1,mount:x=>{
  const cast=DA.sh([['初音未来','#39c5bb'],['镜音铃','#ffa500'],['镜音连','#e6c900'],['巡音流歌','#e89aaa'],['MEIKO','#d80000'],['KAITO','#3155c6']]).slice(0,3),p=cast[0],a=cast[1],b=cast[2];
  const ss=[
    {fx:'exam',scene:'国考考场',who:[p],n:`${p[0]}｜内心`,c:p[1],t:'平时练习时一眼就能报出近似值，可计时器一走，我却不敢落笔，只好退回精算。',o:[['硬撑着继续精算','这能做完眼前一题，却没有解决为什么不敢相信估算。'],['先把这次卡住记下来，考后弄清自己究竟怕什么',1]],ms:900},
    {fx:'rail',scene:'国考后 · 返程高铁',who:[p],n:`${p[0]}｜靠窗座位`,c:p[1],t:'窗外的灯一段段掠过去。真正难受的不是某道题没算完，而是明明平时会估，到了考场却不敢相信自己的结果。',o:[['回家后把这件事说清楚，不再只怪自己胆小',1],['下次做题再快一点就好了','速度已经有了。只加速度，不解决不敢使用的原因。']],ms:1800},
    {fx:'home',scene:'国考后 · 家中',who:[p,a,b],n:`${a[0]}｜聊天`,c:a[1],t:`你回来啦。今天考得怎么样？怎么一路上都没说话？`,o:[['如实说：资料分析会算，却在估算结果前退回了精算',1],['先说没事，把这次卡住藏起来','不把真正卡住的地方说出来，复盘就只能停在情绪上。']],ms:1200},
    {fx:'direction',scene:'国考后 · 家中 · 方向',who:[p,a,b],n:`${b[0]}｜聊天`,c:b[1],t:'你怕的不是算得慢，而是不知道这个快值会偏大还是偏小。方向说不清，当然不敢押给选项。',o:[['先判断估算结果偏大还是偏小',1],['以后只练更快的口算','更快地报出一个没边界的数，只会让犹豫来得更快。']],ms:1200},
    {fx:'range',scene:'国考后 · 家中 · 范围',who:[p,a,b],n:`${a[0]}｜聊天`,c:a[1],t:'只有方向也不够。两个选项贴得很近时，还要知道误差大约多少，会不会跨过相邻选项。',o:[['估出误差范围，再决定能不能停算',1],['方向对了就直接选','方向不能说明偏差是否越过选项边界。']],ms:1850},
    {fx:'fix',scene:'国考后 · 家中 · 修正',who:[p,a,b],n:`${a[0]} 与 ${b[0]}｜聊天`,c:b[1],t:'比如粗算值 270 偏大约 1% 多：270 的 1% 约 2.7，下修约 3，就是 267 附近。能判方向、范围和修正，估算才真正稳定。',o:[['我明白了：不是逼自己敢，而是让判断有依据',1],['只要把 267 这个答案背下来','要带走的是控误方法，不是这一道题的数字。']],ms:1350},
    {fx:'ready',scene:'湖南 3·15 联考 · 清晨',who:[p,a],n:`${a[0]}｜驾驶座`,c:a[1],t:'这次就在本市，不赶高铁。我送你去考点。今天感觉怎么样？',o:[['很稳。方向、范围、修正都练过了，按判断做就行',1],['还是要在车上临时背一遍结论','真正的稳定不是考前再背一句话，而是方法已经能直接调用。']],ms:1000},
    {fx:'focus',scene:'湖南 3·15 联考 · 考场',who:[p],n:`${p[0]}｜作答`,c:p[1],t:'粗算偏大约 1% 多，误差不会跨错选项；下修后落在目标项。判断结束，继续下一题。',o:[['交卷',1]],ms:2250},
    {fx:'wait',scene:'省考后 · 等待出分',who:[p,a,b],n:`${b[0]}｜消息`,c:b[1],t:'成绩查询入口开了。别刷新三次了，点进去看看。',o:[['查询成绩',1]],ms:1000},
    {fx:'legend',scene:'出分日 · 家中',who:[p,a,b],n:`${p[0]}｜成绩页`,c:p[1],t:'笔试成绩：180 分，全省第一。全省第二名 150 分，领先整整 30 分。消息传开后，人们反复谈起这场几乎断层的胜利；那个曾在国考考场不敢相信估算的人，如今凭稳定、清醒而果断的发挥，成为了全省传奇。',o:[],end:1,endDelay:3800}
  ];
  galPlay(x,ss,{talk:1,visual:s=>mindFx(s.fx,p,a,b),status:s=>s.scene.includes('考场')?'考场只执行已经练成的判断。':'把国考时的犹豫拆开说清。'});

}});
