(function(){
const pk=a=>a[Math.random()*a.length|0],n=(a,b)=>a+(Math.random()*(b-a+1)|0);
const optClean=s=>typeof s==='string'?s.replace(/[。！？!?；;，,]+$/,''):s;
const R=(q,a,pool,hint,solution,ex={})=>{a=optClean(a);pool=(pool||[]).map(optClean);return Object.assign({q,a,pool,hint,solution},ex)};
const uq=a=>[...new Set(a)],sh=a=>a.map(v=>[Math.random(),v]).sort((x,y)=>x[0]-y[0]).map(x=>x[1]);
const o=(ans,arr,lim=5)=>{ans=optClean(ans);return sh([ans,...sh(uq((arr||[]).map(optClean)).filter(x=>x!==ans)).slice(0,lim-1)])};
const rs=(x,d=3)=>String((Math.round(x*10**d)/10**d).toFixed(d)).replace(/0+$/,'').replace(/\.$/,'');
const q=(id,title,tags,mk,type)=>({id,title,t:title,tags,type:type||tags,makeQuestion:mk,mk});
const c=(id,title,subs,mode)=>{const x={id,title,t:title,type:'同卡子级别',tags:'同卡子级别',subs};if(mode==='sequence')x.levelType=x.unlockMode=mode;return x};
const add=x=>Game.addLessonTopic('data_analysis_speed_04',x),sec=t=>add({k:'s',t});
Game.beginLesson('data_analysis_speed_04','资料分析速算 04');
window.DA4={pk,n,R,uq,sh,o,rs,q,c,add,sec,done:()=>Game.finishLesson('data_analysis_speed_04',{title:'资料分析速算 04'})};
})();


