const ip=x=>Object.assign(x,{branchType:x.branchType||'internal'});
const rp=x=>Object.assign(x,{branchType:'random'});
const br=(id,t,a)=>a.length===1?ip(Object.assign(a[0],{title:t,t})):c(id,t,a.map(ip),'sequence');
const card=(id,t,a)=>add(c(id,t,a,'sequence'));
const info=(id,t,body,hint,solution)=>({id,title:t,t,info:true,type:'驿站',tags:['驿站'],body,hint,solution});
const mc=(id,title,tags,stem,ans,wrongs,hint,solution)=>q(id,title,tags,()=>R(stem,ans,DA4.o(ans,wrongs,4),hint,solution));
const pickMC=(id,title,tags,items)=>q(id,title,tags,()=>{const x=DA4.pk(items);return R(x.q,x.a,DA4.o(x.a,x.w,4),x.h,x.s)});

